func (q *Queries) RevokeGateway(ctx context.Context, arg RevokeGatewayParams) (Gateway, error) {
	row := q.db.QueryRow(ctx, revokeGateway, arg.ID, arg.OrgID)
	var i Gateway
	err := row.Scan(
		&i.ID,
		&i.OrgID,
		&i.Name,
		&i.TokenHash,
		&i.Version,
		&i.DeploymentType,
		&i.PublicUrl,
		&i.IpAddress,
		&i.LastHeartbeat,
		&i.Status,
		&i.IsActive,
		&i.CreatedAt,
		&i.EnrolledAt,
		&i.RevokedAt,
	)
	return i, err
}

